package com.nextrade.api.config; import com.nextrade.common.identifier.UserId; import com.nextrade.domain.repository.UserRepository; import com.nextrade.domain.user.User; import java.util.*; import java.util.concurrent.*; public final class InMemoryUserRepository implements UserRepository {private final ConcurrentHashMap<UserId,User> byId=new ConcurrentHashMap<>();public Optional<User> findById(UserId id){return Optional.ofNullable(byId.get(id));}public Optional<User> findByUsername(String username){return byId.values().stream().filter(u->u.username().value().equalsIgnoreCase(username)).findFirst();}public Optional<User> findByEmail(String email){return byId.values().stream().filter(u->u.email().value().equalsIgnoreCase(email)).findFirst();}public User save(User user){byId.put(user.id(),user);return user;}public boolean existsByUsername(String v){return findByUsername(v).isPresent();}public boolean existsByEmail(String v){return findByEmail(v).isPresent();}}
